OUT=Path(__file__).resolve().parents[1]
BANK=[]
COL=['#dbe8ff','#fbe7b7','#dcefe9','#eadff7','#f7d9d9','#cfeaf2']
def rect(x,y,w,h,fill='#eaf0ff',r=8):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="#49627e" stroke-width="2"/>'
def ellipse(x,y,rx,ry,fill='#dbe8ff'):return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="{fill}" stroke="#49627e" stroke-width="2"/>'
def line(x,y,a,b,color='#49627e',width=3,arrow=False):return f'<path d="M{x},{y} L{a},{b}" stroke="{color}" stroke-width="{width}" fill="none"'+(' marker-end="url(#arrow)"' if arrow else '')+'/>'
def text(x,y,t,size=15):
 import html
 return f'<text x="{x}" y="{y}" text-anchor="middle" fill="#243b57" font-family="Arial,sans-serif" font-size="{size}">{html.escape(t)}</text>'
def path(d,fill='#dbe8ff',stroke='#49627e'):return f'<path d="{d}" fill="{fill}" stroke="{stroke}" stroke-width="3"/>'
def placement(subject,years,topic):return [{'subject':subject,'year':y,'topic':topic} for y in years]
def add(id,title,p,body,labels,note='Schematic diagram; not to scale.'):
 # labels: answer, target x, target y, explanation, optional aliases
 points=[]
 for i,l in enumerate(labels):
  left=i%2==0;row=i//2;x=45 if left else 655;y=80+row*(275/max(1,(len(labels)+1)//2-1))
  points.append({'id':str(i+1),'answer':l[0],'x':x,'y':round(y),'tx':l[1],'ty':l[2],'explanation':l[3],'aliases':l[4] if len(l)>4 else []})
 BANK.append({'id':id,'title':title,'placements':p,'svg':body,'points':points,'note':note,'authorship':'Original Learning Vault diagram and questions','version':1})
def flow(id,title,p,items,vertical=False):
 n=len(items);body='';labs=[]
 for i,(answer,clue,why) in enumerate(items):
  if vertical:x,y,w,h=230,32+i*360/n,240,300/n
  else:x,y,w,h=115+i*480/n,150,440/n,120
  import textwrap,html
  words=textwrap.wrap(clue,max(8,int(w/7)))
  tspans=''.join(f'<tspan x="{x+w/2}" dy="{0 if j==0 else 15}">{html.escape(word)}</tspan>' for j,word in enumerate(words))
  label=f'<text x="{x+w/2}" y="{y+h/2-(len(words)-1)*7}" text-anchor="middle" fill="#243b57" font-family="Arial,sans-serif" font-size="12">{tspans}</text>'
  body+=rect(x,y,w,h,COL[i%6])+label
  if i<n-1 and id not in {'rock-cycle','thermal','nuclear','marketing','accounting-equation','fitness','energy-systems','experiment','hazard','urban','source-analysis','persuasion','conditioning','carbon-cycle','photoelectric'}:body+=line(x+w/2,y+h+2,x+w/2,y+360/n-4,arrow=True) if vertical else line(x+w+2,y+h/2,x+480/n-5,y+h/2,arrow=True)
  labs.append((answer,x+w/2,y+h/2+20,why))
 add(id,title,p,body,labs,'Label the described stages or parts of this model. Boxes are intentionally unlabelled.')
